-- Generated by `chainindex dbt` from chains/ethereum.yaml and abis/UniswapV3Factory.json. Do not edit: change the chain file or ABI and regenerate.
-- PoolCreated(address,address,uint24,int24,address)
{{ config(
    materialized='view',
    schema='events_ethereum',
    alias='uniswap_v3_factory__pool_created',
    tags=['chains', 'chain_ethereum'],
) }}

select
    toUInt64(1) as chain_id,
    address,
    block_number,
    block_time,
    block_hash,
    transaction_hash,
    transaction_index,
    log_index,
    inserted_at,
    concat('0x', substring(substring(topic1, 3, 64), 25, 40)) as token0,
    concat('0x', substring(substring(topic2, 3, 64), 25, 40)) as token1,
    toUInt32(reinterpretAsUInt256(reverse(unhex(substring(topic3, 3, 64))))) as fee,
    toInt32(reinterpretAsInt256(reverse(unhex(substring(data, 3, 64))))) as tick_spacing,
    concat('0x', substring(substring(data, 67, 64), 25, 40)) as pool
from {{ source('chain_ethereum', 'logs') }}
where topic0 = '0x783cca1c0412dd0d695e784568c96da2e9c22ff989357a2e8b1d9b2b4e6b7118'
  and address in (select address from {{ ref('ethereum__contracts') }} where contract = 'uniswap_v3_factory')
  and (block_number, block_hash) not in (
    select block_number, block_hash from {{ source('chain_ethereum', 'orphaned_blocks') }}
  )
